-- State transitions declared for MailNotification (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION messaging.mail_notifications_notification_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."notification_status" IS DISTINCT FROM OLD."notification_status" AND NOT (
           (COALESCE(OLD."notification_status"::text, ''), COALESCE(NEW."notification_status"::text, '')) IN (('exception', 'bounce'), ('exception', 'pending'), ('pending', 'bounce'), ('pending', 'canceled'), ('pending', 'exception'), ('pending', 'sent'), ('process', 'bounce'), ('process', 'canceled'), ('process', 'exception'), ('process', 'pending'), ('process', 'sent'), ('ready', 'canceled'), ('ready', 'process'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: mail_notifications.notification_status % -> %', OLD."notification_status", NEW."notification_status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mail_notifications_notification_status_transition_check ON messaging.mail_notifications;
CREATE TRIGGER mail_notifications_notification_status_transition_check
    BEFORE UPDATE OF "notification_status" ON messaging.mail_notifications
    FOR EACH ROW EXECUTE FUNCTION messaging.mail_notifications_notification_status_transition_check();
